import styles from './portfolio.module.css';
import Image from 'next/image';
import Link from 'next/link';
import content from '../../data/content.json';

const PortfolioPage = () => {
    return (
        <div className={styles.container}>
            <section className={styles.intro}>
                <h1 className="section-title">
                    {content.portfolio.introTitle.split(' ').map((word, i) =>
                        i === 1 ? <span key={i} className="accent-text">{word} </span> : word + ' '
                    )}
                </h1>
                <p className={styles.introText}>
                    {content.portfolio.introText}
                </p>
            </section>

            <section className={styles.portfolioGrid}>
                {content.portfolio.works.map((work: any, idx: number) => (
                    <Link key={idx} href={`/portfolio/${work.slug}`} className={`${styles.portfolioCard} glass-card`}>
                        <div className={styles.imageOverlay}>
                            <Image
                                src={work.image}
                                alt={work.title}
                                width={600}
                                height={450}
                                className={styles.cardCover}
                            />
                            <div className={styles.hoverInfo}>
                                <span>Смотреть кейс</span>
                            </div>
                        </div>
                        <div className={styles.cardInfo}>
                            <h3>{work.title}</h3>
                            <p className={styles.cardDesc}>{work.desc}</p>
                            <div className={styles.cardFooter}>
                                <div className={styles.materialTag}>
                                    {work.material}
                                </div>
                                <div className={styles.viewMore}>
                                    Кейс <span>→</span>
                                </div>
                            </div>
                        </div>
                    </Link>
                ))}
            </section>
        </div>
    );
};

export default PortfolioPage;
